<script setup>
import { ref,watch } from 'vue'; import { useRoute } from 'vue-router'; import { api } from '../services/api'
const route=useRoute(), albums=ref([]),cats=ref([]),search=ref(''),category=ref(''),sort=ref('newest'),page=ref(1),last=ref(1),error=ref('')
async function load(){try{const r=await api.get('/albums',{params:{search:search.value,category:category.value,sort:sort.value,page:page.value}}); albums.value=r.data.data;last.value=r.data.last_page;error.value=''}catch{error.value='Album tidak dapat dimuat.'}}
api.get('/categories').then(r=>cats.value=r.data).catch(()=>{});watch(()=>route.query.category,v=>{category.value=v||'';page.value=1;load()},{immediate:true});watch([search,category,sort],()=>{page.value=1;load()});watch(page,load)
</script>
<template><main class="wrap listing"><div class="eyebrow"><i></i> ARSIP FOTO JAKARTA</div><h1>Album Foto</h1><p>Temukan album berdasarkan nama, kategori, atau tanggal kegiatan.</p><div class="filters"><input v-model="search" aria-label="Cari album" placeholder="Cari nama album..."><select v-model="category" aria-label="Filter kategori"><option value="">Semua kategori</option><option v-for="c in cats" :value="c.slug">{{c.name}}</option></select><select v-model="sort" aria-label="Urutan album"><option value="newest">Terbaru</option><option value="oldest">Terlama</option></select></div><p v-if="error" class="notice">{{error}}</p><p v-else-if="!albums.length" class="notice">Tidak ada album ditemukan.</p><div class="album-grid"><router-link v-for="a in albums" :key="a.id" :to="'/albums/'+a.slug" class="card"><div class="card-image"><img v-if="a.cover" :src="a.cover.thumbnail_url" loading="lazy" :alt="a.title"><span v-else class="placeholder">JAKARTA<br>PHOTO GALLERY</span><span class="card-tag">{{a.category?.name}}</span></div><div class="card-meta">{{a.event_date?.slice(0,10) || 'Tanggal tidak tersedia'}} <span>{{a.photos_count}} foto</span></div><h3>{{a.title}} <span>↗</span></h3></router-link></div><div class="pagination"><button :disabled="page<=1" @click="page--">← Sebelumnya</button><span>{{page}} / {{last}}</span><button :disabled="page>=last" @click="page++">Berikutnya →</button></div></main></template>

